export const getListBizProviderOrdersUrl = (params?: ListBizProviderOrdersParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/biz/provider/orders?${stringifiedParams}` : `/api/biz/provider/orders`
}

